+const { useState } = React;
+
+const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+const PHONE_RE = /^\+?[0-9][0-9\s().-]{6,}$/;
+
+function FormField({ id, label, type, value, onChange, onBlur, error, required, optional, placeholder, helper, autoComplete }) {
+  return (
+    <div className={"form-field" + (error ? " has-error" : "")}>
+      <label htmlFor={id}>
+        {label}
+        {optional && <span className="optional">(optional)</span>}
+      </label>
+      <input
+        id={id}
+        name={id}
+        type={type}
+        value={value}
+        onChange={onChange}
+        onBlur={onBlur}
+        placeholder={placeholder}
+        autoComplete={autoComplete}
+        aria-invalid={!!error}
+        aria-describedby={error ? `${id}-error` : helper ? `${id}-helper` : undefined}
+        required={required}
+      />
+      {error
+        ? <p id={`${id}-error`} className="error-text">{error}</p>
+        : helper && <p id={`${id}-helper`} className="helper-text">{helper}</p>}
+    </div>
+  );
+}
+
+function validateField(name, value) {
+  const v = value.trim();
+  if (name === "fullName") {
+    if (!v) return "Full name is required.";
+    if (v.length < 2) return "Please enter your full name.";
+    return "";
+  }
+  if (name === "email") {
+    if (!v) return "Email address is required.";
+    if (!EMAIL_RE.test(v)) return "Please enter a valid email address.";
+    return "";
+  }
+  if (name === "phone") {
+    if (!v) return "";
+    if (!PHONE_RE.test(v)) return "Please enter a valid phone number (e.g. +1 555 123 4567).";
+    return "";
+  }
+  return "";
+}
+
+function ContactForm() {
+  const [values, setValues] = useState({ fullName: "", email: "", phone: "" });
+  const [errors, setErrors] = useState({});
+  const [touched, setTouched] = useState({});
+  const [submitted, setSubmitted] = useState(false);
+
+  const handleChange = (e) => {
+    const { name, value } = e.target;
+    setValues((v) => ({ ...v, [name]: value }));
+    if (touched[name]) {
+      setErrors((er) => ({ ...er, [name]: validateField(name, value) }));
+    }
+  };
+
+  const handleBlur = (e) => {
+    const { name, value } = e.target;
+    setTouched((t) => ({ ...t, [name]: true }));
+    setErrors((er) => ({ ...er, [name]: validateField(name, value) }));
+  };
+
+  const handleSubmit = (e) => {
+    e.preventDefault();
+    const newErrors = {
+      fullName: validateField("fullName", values.fullName),
+      email: validateField("email", values.email),
+      phone: validateField("phone", values.phone),
+    };
+    setErrors(newErrors);
+    setTouched({ fullName: true, email: true, phone: true });
+    const hasError = Object.values(newErrors).some(Boolean);
+    if (!hasError) {
+      setSubmitted(true);
+    } else {
+      setSubmitted(false);
+    }
+  };
+
+  return (
+    <div className="card">
+      <div className="card-header">
+        <p className="eyebrow">Support</p>
+        <h1>Get in touch</h1>
+        <p>Send us a message and a member of our support team will get back to you shortly.</p>
+      </div>
+      <form onSubmit={handleSubmit} noValidate>
+        <FormField
+          id="fullName"
+          label="Full name"
+          type="text"
+          value={values.fullName}
+          onChange={handleChange}
+          onBlur={handleBlur}
+          error={errors.fullName}
+          required
+          placeholder="Jane Doe"
+          autoComplete="name"
+        />
+        <FormField
+          id="email"
+          label="Email address"
+          type="email"
+          value={values.email}
+          onChange={handleChange}
+          onBlur={handleBlur}
+          error={errors.email}
+          required
+          placeholder="jane@example.com"
+          autoComplete="email"
+        />
+        <FormField
+          id="phone"
+          label="Phone number"
+          type="tel"
+          value={values.phone}
+          onChange={handleChange}
+          onBlur={handleBlur}
+          error={errors.phone}
+          optional
+          placeholder="+1 555 123 4567"
+          helper="Include country code, e.g. +1 555 123 4567. Digits, spaces, dashes, parentheses allowed."
+          autoComplete="tel"
+        />
+        <button type="submit" className="submit-btn">Send message</button>
